  "input": {
    "text": "是不是都能叫祖先崇拜？我担心这样概括不准确。",
    "language": "Chinese",
    "voice_setting": {
      "voice_id": "qwen3-profile-2388c3a1c03950cd",
      "seed": 242560699,
